const webhook = $('Webhook').first();

const manifest = JSON.parse(webhook.json.body.manifest);
const binaries = webhook.binary || {};

const binaryKeys = Object.keys(binaries).sort((a, b) => {
    return parseInt(a.replace("documents", "")) - parseInt(b.replace("documents", ""));
});

if (binaryKeys.length !== manifest.length) {
    throw new Error(
        `Manifest (${manifest.length}) and binaries (${binaryKeys.length}) do not match.`
    );
}

const output = [];

for (let i = 0; i < manifest.length; i++) {

    const file = manifest[i];
    const binary = binaries[binaryKeys[i]];

    output.push({
        json: {
            filename: file.filename,
            folderId: file.folderId,
            relativePath: file.relativePath,
            binaryKey: binaryKeys[i],
        },
        binary: {
            data: binary,
        },
    });
}

return output;

const webhook = $('Webhook').first();

const manifest = JSON.parse(webhook.json.body.manifest);
const binaries = webhook.binary || {};

const output = [];

for (const file of manifest) {

    // Use ONLY the original binary key from the manifest
    const binaryKey = file.binaryKey;

    if (!binaryKey) {
        throw new Error(
            `binaryKey missing in manifest for ${file.filename}`
        );
    }

    const binary = binaries[binaryKey];

    if (!binary) {
        throw new Error(
            `Binary not found.\n\nExpected: ${binaryKey}\n\nAvailable:\n${Object.keys(binaries).join('\n')}`
        );
    }

    output.push({
        json: {
            filename: file.filename,
            folderId: file.folderId,
            relativePath: file.relativePath,
            binaryKey: binaryKey
        },
        binary: {
            data: binary
        }
    });

}

return output;

const items = $input.all();

const mismatch = [];

for (const item of items) {

  const data = item.json;

  if (!data.verification) continue;

  for (const field in data.verification) {

    const check = data.verification[field];

    if (check.status !== "Matched") {

      mismatch.push({

        Aspirant_ID: data.aspirant_id,

        Aspirant_Name:
          data.verification.name?.document_value || "",

        Field: field,

        Status: check.status,

        Document_Value:
          check.document_value || "",

        Database_Value:
          check.database_value || "",

        Reason:
          check.reason || "",

        Overall_Status:
          data.overall_status,

        Match_Percentage:
          data.match_percentage

      });

    }
  }
}

return mismatch.map(row => ({
  json: row
}));

const ExcelJS = require('exceljs');

const items = $input.all();

const workbook = new ExcelJS.Workbook();

for (const item of items) {

    const sheetName = item.json.sheet;
    const rows = item.json.data || [];

    const worksheet = workbook.addWorksheet(sheetName);

    if (rows.length === 0) {
        worksheet.addRow(["No Data"]);
        continue;
    }

    // Create columns
   worksheet.columns = Object.keys(rows[0]).map(key => ({
    header: key,
    key: key,
    width: Math.max(key.length + 2, 15)
}));

    const headerRow = worksheet.getRow(1);

headerRow.font = {
    bold: true
};

headerRow.alignment = {
    horizontal: "center",
    vertical: "middle"
};

headerRow.height = 22;

    // Add data
    rows.forEach(row => worksheet.addRow(row));

  worksheet.eachRow((row, rowNumber) => {

    if (rowNumber === 1) return;

    row.alignment = {
        wrapText: true,
        vertical: "middle"
    };

});

}

const buffer = await workbook.xlsx.writeBuffer();

return [
{
    json: {
        fileName: "Verification_Report.xlsx"
    },
    binary: {
        data: {
            data:      
            Buffer.from(buffer).toString("base64"),
            mimeType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            fileName: "Verification_Report.xlsx"
        }
    }
}
];

return [
  {
    json: {
      success: true,
      message: "Verification report generated"
    },
    binary: $input.first().binary
  }
];

const groups = {};

for (const item of $input.all()) {

  const doc = item.json;

  if (!doc.relativePath) continue;


  const pathParts = doc.relativePath.split("/");


  // Aspirant folder is always the folder before the filename
  const aspirantId = pathParts[pathParts.length - 2];


  if (!aspirantId) continue;


  if (!groups[aspirantId]) {

    groups[aspirantId] = {
      aspirantId,
      totalDocuments: 0,
      documents: [],
      binary: {}
    };

  }


  groups[aspirantId].totalDocuments++;


  groups[aspirantId].documents.push({
    filename: doc.filename,
    binaryKey: doc.binaryKey,
    relativePath: doc.relativePath
  });


  // Preserve all PDF binaries
  for (const [key, value] of Object.entries(item.binary || {})) {

    groups[aspirantId].binary[doc.binaryKey] = value;

  }

}


return Object.values(groups).map(group => ({

  json: {
    aspirantId: group.aspirantId,
    totalDocuments: group.totalDocuments,
    documents: group.documents
  },

  binary: group.binary

}));

