const items = $input.all();

const matched = [];
const mismatch = [];
const comparison = [];

for (const item of items) {

  const data = item.json;

  // Matched Data
  if (data.Name_Status) {
    matched.push(data);
  }

  // Mismatch Data
  else if (data.Field) {
    mismatch.push(data);
  }

  // Comparison Data
  else if (
    data.Document_Name !== undefined &&
    data.Database_Name !== undefined
  ) {
    comparison.push(data);
  }

}

return [
  {
    json: {
      sheet: "Matched_Data",
      data: matched
    }
  },
  {
    json: {
      sheet: "Mismatch_Data",
      data: mismatch
    }
  },
  {
    json: {
      sheet: "Comparison_Data",
      data: comparison
    }
  }
];

const input = $input.first();

const aspirantId = input.json.aspirantId;
const binaries = input.binary || {};

const output = [];

const keys = Object.keys(binaries).sort();

for (let i = 0; i < keys.length; i++) {
  const key = keys[i];
  const file = binaries[key];

  output.push({
    json: {
      aspirantId,
      order: i,
      binaryKey: key,
      fileName: file.fileName,
    },
    binary: {
      data: file,
    },
  });
}

return output;
